message.content:
{
  "title": "The Gilded Cage",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The party arrives at the ruined city gates.",
      "visual_description": "Crumbling stone archways overgrown with thorny vines, rusted portcullis half-raised, faded royal banners hanging tattered in the wind.",
      "characters": ["Elena", "Ronan", "Mira"]
    },
    {
      "scene_number": 2,
      "caption": "Frightened townspeople warn the party of the cursed towers.",
      "visual_description": "Huddled group of dirty, terrified villagers in rags pointing toward black spires that pulse with unnatural light, their faces gaunt and eyes wide.",
      "characters": ["Elena", "Ronan", "Mira", "Villager Leader"]
    },
    {
      "scene_number": 3,
      "caption": "Armored patrol blocks the main road.",
      "visual_description": "Three soldiers in blackened plate armor with glowing red visors march in lockstep, their shields emblazoned with a broken crown emblem, torches flickering on their pauldrons.",
      "characters": ["Elena", "Ronan", "Mira", "Patrol Soldier 1", "Patrol Soldier 2", "Patrol Soldier 3"]
    },
    {
      "scene_number": 4,
      "caption": "The party sneaks through a forgotten side passage.",
      "visual_description": "Narrow, debris-choked alley between collapsed buildings, moonlight filtering through cracked ceilings, a rat scurrying over broken pottery.",
      "characters": ["Elena", "Ronan", "Mira"]
    },
    {
      "scene_number": 5,
      "caption": "Ronan hears rumors of a dragon from a street urchin.",
      "visual_description": "A scruffy child with dirt-streaked face crouches behind a barrel, whispering excitedly, his hand describing a large shape in the air, shadows of patrols passing nearby.",
      "characters": ["Ronan", "Street Urchin"]
    },
    {
      "scene_number": 6,
      "caption": "The first cursed tower looms before them.",
      "visual_description": "Twisted obsidian spire with glowing runes that shift like living serpents, a single iron door pulsating with a sickly green light, the air thick with sulfur.",
      "characters": ["Elena", "Ronan", "Mira"]
    },
    {
      "scene_number": 7,
      "caption": "A magic door tests the party's resolve.",
      "visual_description": "Ornately carved door with a face that speaks, its eyes glowing amber, offering a vision of treasure through a crack that slowly widens.",
      "characters": ["Elena", "Ronan", "Mira", "Magic Door Face"]
    },
    {
      "scene_number": 8,
      "caption": "They enter the tower and confront an illusion of their greatest desires.",
      "visual_description": "A grand hall filled with gold, a feast table, and ghostly figures of loved ones beckoning, the walls shimmering like a mirage.",
      "characters": ["Elena", "Ronan", "Mira"]
    },
    {
      "scene_number": 9,
      "caption": "Mira breaks the illusion with a sharp word.",
      "visual_description": "Mira shouts, her hand glowing with white light as the hall cracks and fades, revealing a stone chamber with chains hanging from the ceiling.",
      "characters": ["Elena", "Ronan", "Mira"]
    },
    {
      "scene_number": 10,
      "caption": "They rescue the first prisoner from a crystal cage.",
      "visual_description": "A glowing crystal suspended by chains, a frail figure inside with hands pressed against the facets, Elena reaching out to touch the surface.",
      "characters": ["Elena", "Ronan", "Mira", "Prisoner Kael"]
    },
    {
      "scene_number": 11,
      "caption": "A patrol corners them in a guardroom.",
      "visual_description": "Circular room with weapon racks, four armored soldiers entering from both doors, swords drawn, the party back-to-back in the center.",
      "characters": ["Elena", "Ronan", "Mira", "Prisoner Kael", "Patrol Soldier 1", "Patrol Soldier 2", "Patrol Soldier 3", "Patrol Soldier 4"]
    },
    {
      "scene_number": 12,
      "caption": "They escape through a secret passage hidden behind a tapestry.",
      "visual_description": "Ronan pulls a frayed tapestry depicting a dragon, revealing a dark narrow staircase descending into damp-smelling darkness.",
      "characters": ["Elena", "Ronan", "Mira", "Prisoner Kael"]
    },
    {
      "scene_number": 13,
      "caption": "The party rests in a collapsed chapel.",
      "visual_description": "Broken stained-glass window casting colored light on a cracked altar, stone pews overturned, the group catching their breath among the rubble.",
      "characters": ["Elena", "Ronan", "Mira", "Prisoner Kael"]
    },
    {
      "scene_number": 14,
      "caption": "A dragon's shadow passes overhead.",
      "visual_description": "Through a hole in the chapel roof, a massive winged silhouette blocks the sun, scales glinting red, a roar that shakes the stones.",
      "characters": ["Elena", "Ronan", "Mira", "Prisoner Kael"]
    },
    {
      "scene_number": 15,
      "caption": "They reach the inner courtyard and find the last prisoner.",
      "visual_description": "Open courtyard with a gallows, a hooded figure bound to a post, surrounded by a ring of blue fire.",
      "characters": ["Elena", "Ronan", "Mira", "Prisoner Kael", "Prisoner Lira"]
    },
    {
      "scene_number": 16,
      "caption": "The dragon lands on the keep, blocking the exit.",
      "visual_description": "Massive red dragon perches on the central tower, wings spread, tail sweeping the courtyard, eyes fixed on the party.",
      "characters": ["Elena", "Ronan", "Mira", "Prisoner Kael", "Prisoner Lira", "Dragon"]
    },
    {
      "scene_number": 17,
      "caption": "Elena uses a banner as a distraction to slip past the dragon.",
      "visual_description": "Elena tears a royal banner from a pole and waves it, drawing the dragon's attention as the others sprint toward the bridge, the dragon's head turning with a growl.",
      "characters": ["Elena", "Ronan", "Mira", "Prisoner Kael", "Prisoner Lira", "Dragon"]
    },
    {
      "scene_number": 18,
      "caption": "The final escape across the crumbling bridge.",
      "visual_description": "Ancient stone bridge spanning a chasm, missing sections and cracked pillars, the party running as the dragon's fire engulfs the far end, the bridge collapsing behind them.",
      "characters": ["Elena", "Ronan", "Mira", "Prisoner Kael", "Prisoner Lira", "Dragon"]
    }
  ]
}

